<div class="page-head"><div><a class="back-link" href="<?= e(url('admins')) ?>">→ <?= e(tr('بازگشت به مدیران','Back to administrators')) ?></a><h1><?= e($pageTitle) ?></h1></div></div>
<form method="post" class="panel form-panel" autocomplete="off"><?= csrf_field() ?><div class="form-section"><h2><?= e(tr('اطلاعات حساب','Account details')) ?></h2><div class="form-grid"><label><span><?= e(tr('نام کاربری','Username')) ?> *</span><input name="username" dir="ltr" value="<?= e($admin['username']??'') ?>" required></label><label><span><?= $id?e(tr('رمز جدید (خالی = بدون تغییر)','New password (blank = unchanged)')):e(tr('رمز عبور (حداقل ۱۰ نویسه)','Password (minimum 10 characters)') ) ?></span><input type="password" name="password" minlength="10" <?= $id?'':'required' ?>></label><label><span><?= e(tr('نام کامل','Full name')) ?></span><input name="full_name" value="<?= e($admin['full_name']??'') ?>"></label><label><span><?= e(tr('تلفن','Phone')) ?></span><input name="phone" dir="ltr" value="<?= e($admin['phone']??'') ?>"></label><label><span><?= e(tr('نقش','Role')) ?></span><select name="role"><?php foreach(['superadmin','operator','billing','viewer'] as $role):?><option value="<?= $role ?>" <?= ($admin['role']??'viewer')===$role?'selected':'' ?>><?= e($role) ?></option><?php endforeach;?></select></label><label><span><?= e(tr('زبان پیش‌فرض','Default language')) ?></span><select name="language"><option value="fa" <?= ($admin['language']??'fa')==='fa'?'selected':'' ?>>فارسی</option><option value="en" <?= ($admin['language']??'')==='en'?'selected':'' ?>>English</option></select></label><label class="check-card inline-check"><input type="checkbox" name="is_active" value="1" <?= !isset($admin['is_active'])||!empty($admin['is_active'])?'checked':'' ?>><span><strong><?= e(tr('حساب فعال','Account enabled')) ?></strong><small><?= e(tr('امکان ورود به پنل','Can sign in to the panel')) ?></small></span></label></div></div><div class="form-actions"><a class="button ghost" href="<?= e(url('admins')) ?>"><?= e(tr('انصراف','Cancel')) ?></a><button class="button primary"><?= e(tr('ذخیره مدیر','Save administrator')) ?></button></div></form>

